import pyomo.environ as pyo

DATA = {
    "capacity_ml": {"vintage": 500, "regular": 750},
    "vine_available_ml": 100000,
    "regular_to_vintage_ratio": 4,
    "min_vintage_bottles": 10,
}

BOTTLES = ["vintage", "regular"]


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Set of bottle types
    model.BOTTLES = pyo.Set(initialize=BOTTLES)

    # Decision variables: number of each bottle type produced (integer, nonnegative).
    # Vintage bottles have a lower bound of min_vintage_bottles ("at least 10 vintage bottles").
    def vintage_bounds(m):
        return (d["min_vintage_bottles"], None)

    model.bottles_made = pyo.Var(
        model.BOTTLES,
        within=pyo.NonNegativeIntegers,
        bounds=lambda m, b: (d["min_vintage_bottles"], None) if b == "vintage" else (0, None),
    )

    # Objective: maximize total number of bottles produced
    model.obj = pyo.Objective(
        expr=sum(model.bottles_made[b] for b in model.BOTTLES),
        sense=pyo.maximize,
    )

    # Constraint 1: total vine used cannot exceed available vine (ml)
    def vine_availability_rule(m):
        return sum(
            d["capacity_ml"][b] * m.bottles_made[b] for b in m.BOTTLES
        ) <= d["vine_available_ml"]

    model.vine_availability = pyo.Constraint(rule=vine_availability_rule)

    # Constraint 2: regular bottles must be at least ratio times vintage bottles
    def ratio_rule(m):
        return (
            m.bottles_made["regular"]
            >= d["regular_to_vintage_ratio"] * m.bottles_made["vintage"]
        )

    model.regular_to_vintage_ratio = pyo.Constraint(rule=ratio_rule)

    return model


